namespace sv_6d730a952e88487d8200d94b43bce07d.Services;

/// <summary>
/// Scoped service (per-circuit) that holds shared state for warehouse selection
/// and inventory alert counts. Provides change notification events so unrelated
/// components can stay synchronized.
/// </summary>
public class WarehouseStateService : IDisposable
{
    private string _selectedWarehouseId = "WH-001";
    private int _lowStockCount;

    public static readonly List<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-001", "Warehouse A"),
        ("WH-002", "Warehouse B"),
        ("WH-003", "Warehouse C"),
        ("WH-004", "Warehouse D"),
    ];

    public string SelectedWarehouseId
    {
        get => _selectedWarehouseId;
        set
        {
            if (_selectedWarehouseId != value)
            {
                _selectedWarehouseId = value;
                NotifyWarehouseChanged();
            }
        }
    }

    public string SelectedWarehouseName =>
        AvailableWarehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId).Name ?? "Unknown";

    public int LowStockCount
    {
        get => _lowStockCount;
        set
        {
            if (_lowStockCount != value)
            {
                _lowStockCount = value;
                NotifyAlertCountChanged();
            }
        }
    }

    /// <summary>
    /// Fired when the selected warehouse changes.
    /// </summary>
    public event Action? OnWarehouseChanged;

    /// <summary>
    /// Fired when the low-stock alert count changes.
    /// </summary>
    public event Action? OnAlertCountChanged;

    private void NotifyWarehouseChanged() => OnWarehouseChanged?.Invoke();
    private void NotifyAlertCountChanged() => OnAlertCountChanged?.Invoke();

    public void Dispose()
    {
        OnWarehouseChanged = null;
        OnAlertCountChanged = null;
    }
}

namespace sv_6d730a952e88487d8200d94b43bce07d.Services;

/// <summary>
/// Simulates a database query for low-stock item counts.
/// Registered as scoped so each circuit gets its own instance.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    /// <summary>
    /// Simulates checking inventory for items below minimum stock levels.
    /// Returns a random count between 0 and 15.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate async database call
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }
}

