@rendermode InteractiveServer
@using sv_6d730a952e88487d8200d94b43bce07d.Services
@inject WarehouseStateService State
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm"
            value="@State.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        State.SelectedWarehouseId = e.Value?.ToString() ?? "WH-001";
    }

    public void Dispose()
    {
        State.OnWarehouseChanged -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@using sv_6d730a952e88487d8200d94b43bce07d.Services
@inject WarehouseStateService State
@implements IDisposable

<span class="alert-badge position-relative">
    @if (State.LowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@State.LowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        State.OnAlertCountChanged += OnStateChanged;
        State.OnWarehouseChanged += OnStateChanged;
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        State.OnAlertCountChanged -= OnStateChanged;
        State.OnWarehouseChanged -= OnStateChanged;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@using sv_6d730a952e88487d8200d94b43bce07d.Services
@inject WarehouseStateService State
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @State.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">
                    <strong>@State.SelectedWarehouseName</strong>
                    <span class="text-muted">(@State.SelectedWarehouseId)</span>
                </p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card @(State.LowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 fw-bold @(State.LowStockCount > 5 ? "text-danger" : "text-success")">
                    @State.LowStockCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level &bull; Refreshes every 10s
                </p>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <p class="card-text">
                    <span class="badge bg-info">Active</span>
                    Last checked: @_lastChecked?.ToString("HH:mm:ss") ?? "—"
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime? _lastChecked;

    protected override void OnInitialized()
    {
        State.OnWarehouseChanged += OnWarehouseChanged;
        State.OnAlertCountChanged += OnAlertCountChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch
            await PollAlerts();
            // Start periodic polling every 10 seconds
            StartPolling();
        }
    }

    private void StartPolling()
    {
